window.RP_SESSION={"id":"S-adbeb9c99125","messages":[{"id":"RP-II-0099983","time":"2026-05-12T02:28:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"푼기윌라 마을에서 식용으로 재배된 버섯을 좀 보내 줬습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099984","time":"2026-05-12T02:29:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"코크두 씨도 갓 잡은 신선한 닭고기를 보내줬군요.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099985","time":"2026-05-12T02:30:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"성실한 농부 슈미트도 마침 완두콩 등의 몇 가지 채소들을 보내 줬군요.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099986","time":"2026-05-12T02:32:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 모아서 1인분이 될 정도로 계량해서 야식을 만들어 먹기로 결정했습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099987","time":"2026-05-12T02:33:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"닭고기는 먼저 작은 녀석으로 골라서 뼈를 가능한 한 단도로 발라내어 정육합니다. 그리고","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099988","time":"2026-05-12T02:33:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099989","time":"2026-05-12T02:33:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'님드 알 쿠라이시'의 지능 판정 :\n[6] + [0] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0099990","time":"2026-05-12T02:33:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엥?","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099991","time":"2026-05-12T02:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099992","time":"2026-05-12T02:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[7] + [1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0099993","time":"2026-05-12T02:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"음음. 그렇지.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099994","time":"2026-05-12T02:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고기를 정육한 뒤 손으로는 뼈를 치우고 팬에 기름을 부으며 염동으로 정육된 닭고기 덩어리를 들어 팬에 노릇하게 굽기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099995","time":"2026-05-12T02:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"닭고기가 맛있는 색과 향기를 풍기며 표면부터 구워지자 버섯과 채소, 완두콩을 넣는다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099996","time":"2026-05-12T02:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099997","time":"2026-05-12T02:36:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[7] + [1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0099998","time":"2026-05-12T02:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"올바른 양의 재료들을 넣은 덕에 재료에서 나온 수분으로 서로가 타지 않고 잘 볶아진다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0099999","time":"2026-05-12T02:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"소금으로 간단하게 간을 하고 접시에 담은 뒤 맥주를 가져온다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100000","time":"2026-05-12T02:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100001","time":"2026-05-12T02:37:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 매력 판정 :\n[1] + [-1] = [0]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0100002","time":"2026-05-12T02:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"플레이팅은 망했네.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100003","time":"2026-05-12T02:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 그닥 맛있어 보이지 않지만 맛있는 야식을 맥주와 함께 즐기고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100004","time":"2026-05-12T04:21:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"@주디스 던","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100005","time":"2026-05-12T04:23:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"레마가 음식을 즐기고 있을 때였습니다. 똑똑똑. 세 번의 문 두드리는 소리가 울려퍼졌습니다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100006","time":"2026-05-12T04:24:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“어….음… 아무도 안계시나요?”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100007","time":"2026-05-12T04:24:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 누, 누구세요? \"\n\n맥주로 입 안을 씻어내고 길드 정문 앞으로 걸어나가자 보이는 것은... 잘생긴 미소년?\n\n\" 어머, 무, 무슨 일로 찾아오셨나요? \"\n\n이런 밤중. 아니, 심지어 곧 아카쿠나 님드가 깨어날 새벽 시간에 모르는. 길드원이 아닌 사람에 길드 앞에 나타나서 당황했지만 일단 잘생겨서 오케이라고 생각하는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100008","time":"2026-05-12T04:29:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“… 여기가 어설픈 용맹이 맞나요?”\n\n이 새벽에 문을 두드린 것 치고는 소심하게 대답한다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100009","time":"2026-05-12T04:30:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"분명 길드이니만큼 우락부락하게 생긴 형님들이 맞이할거라고 생각한 퀀시는 당황해서 눈의 초점이 떨렸지만.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100010","time":"2026-05-12T04:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네. 어설픈 용맹이 마, 맞아요. \"\n\n너무 늦은 시간이라 지금 꼴이 어떤지 자신도 모르는데. 술 마시고 있지 말걸. 길드원이 아니면 용건이 있는 사람인가? 이 주변에 길드원들 중 몇몇 말고는 이렇게 잘생긴 사람은 못 봤던 것 같은데.\n\n\" 무엇을 도, 도와 드릴까요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100011","time":"2026-05-12T04:37:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“아.. 다행이네요…“\n\n접수원 같은 분이실까…?","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100012","time":"2026-05-12T04:37:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"”가입하려고 왔어요…!”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100013","time":"2026-05-12T04:39:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"잘생겨보이는 것은 아마 술의 탓일 가능성이…","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100014","time":"2026-05-12T04:40:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"어딘가 베이기도 하였고 먼지가 잔뜩 묻은 복장을 하고 있는 퀸시. 아마 이곳에 오기까지 많은 고난을 거친 모습이였다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100015","time":"2026-05-12T04:40:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 일단 와서 아, 앉아요. 밥이라도 드릴게요. \"\n\n맛있는 닭고기 볶음. 그리고...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100016","time":"2026-05-12T04:40:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100017","time":"2026-05-12T04:40:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 매력 판정 :\n[5] + [-1] = [4]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0100018","time":"2026-05-12T04:40:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"플레이팅은 이번에도 대참사.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100019","time":"2026-05-12T04:41:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 일단 밥 먹으면서 얘기해요. \"\n\n재료가 좀 살아있는 음식물 쓰레기처럼 보이는 것을 접시에 나름 정성스레 담아 내준다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100020","time":"2026-05-12T04:43:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“어… 네!”\n\n맛있는 음식들이 한 곳에 모여 끔찍한 것이 되었다. 그래도 거부할 수 없었기에 자리에 앉았다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100021","time":"2026-05-12T04:44:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"맛있는 고기도 이것저것 모아놓으면 꿀꿀이죽처럼 보이는구나.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100022","time":"2026-05-12T04:45:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"플레이팅이 부끄러운지 고개를 푹 숙인다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100023","time":"2026-05-12T04:45:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"그런 레마를 바라보고는 당황해서 황급히 입을 떼었다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100024","time":"2026-05-12T04:45:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 길드 가, 가입은 스텔라 씨가 이, 일어나셔아 정식으로 가, 가능할거에요. 방 배, 배정도 마찬가지구요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100025","time":"2026-05-12T04:46:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“스텔라…씨요?”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100026","time":"2026-05-12T04:46:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"누구지..","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100027","time":"2026-05-12T04:46:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 야식만 먹고 자, 자려고 했는데... 괜찮으시면 일단 여기 아, 앉아서 부길드장님이 일어나실 때 까, 까지 기다릴 수 있을까요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100028","time":"2026-05-12T04:47:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“스텔라씨가 부길드장님이신가요..?”\n\n그런 말은 없었지만 아까의 말을 생각해보면.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100029","time":"2026-05-12T04:48:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네, 마, 맞아요. 죄송해요, 설명이 부, 부족했네요. \"\n\n제르지에게 맥주가 든 잔을 건내주며.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100030","time":"2026-05-12T04:49:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“아.. 아니에요..”\n\n괜히 머쓱해 하는 퀸시.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100031","time":"2026-05-12T04:49:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“저 이거는… 술이죠?“","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100032","time":"2026-05-12T04:49:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 맥주라도 마, 마셔요. 먼 길 오시느라 지, 지치셨을 텐데. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100033","time":"2026-05-12T04:50:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 맞아요. 길드에 술을 마, 만드는 분이 계셔서. 부담 없이 마, 마실 수 있어요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100034","time":"2026-05-12T04:51:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"술을 빤히 바라보았다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100035","time":"2026-05-12T04:51:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 혹시 수, 술을 안 드시나요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100036","time":"2026-05-12T04:52:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“가.. 감사합니다.”\n\n입은 데지 않았다. 익숙지 않으니깐…\n\n”그… 그건 아닌데….”\n\n당황한 얼굴이다. 맞다는 소리.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100037","time":"2026-05-12T04:52:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“… 익숙하지 않아서요. 죄송해요.”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100038","time":"2026-05-12T04:52:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"귀여워.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100039","time":"2026-05-12T04:53:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"쓰다듬고 싶은 마음을 억눌러 참으며 깨끗한 물을 한 잔 가져다 준다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100040","time":"2026-05-12T04:53:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“배려해주셔서 감사해요..”\n\n물을 받아들었다. 친절하신 분이구나.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100041","time":"2026-05-12T04:54:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"그리고 음식을 보았다. 거절하면 민폐다. 한 입 시도해본다!","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100042","time":"2026-05-12T04:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 처, 천만에요. \"\n\n본인이 맥주를 마시기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100043","time":"2026-05-12T04:54:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100044","time":"2026-05-12T04:54:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 9 = 9\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0100045","time":"2026-05-12T04:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"굿","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100046","time":"2026-05-12T04:55:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"이 맛은…! 먹을만한 맛있는 맛이다!","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100047","time":"2026-05-12T04:56:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“맛있네요… 감사합니다! 생각해보니.. 아직 가입도 안했는데 이런걸 받아도 될지..“","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100048","time":"2026-05-12T04:56:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 가입 하시면 우, 우리 동료가 되실테니까요! \"\n\n맥주 잔을 들고.\n\n\" 사람들은 이, 이럴 때 잔을 부딪히면서 짠이라고 마, 말하더라구요. 우리도 해요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100049","time":"2026-05-12T04:57:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"건배는.. 맥주잔끼리 하는게 아니였던가?","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100050","time":"2026-05-12T04:57:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"헤헤!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100051","time":"2026-05-12T04:57:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"어쨌든 물잔을 받아들고는 들었다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100052","time":"2026-05-12T04:58:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 짠! \"\n\n잔을 부딪히고 맥주를 꿀꺽꿀꺽 잘도 마시는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100053","time":"2026-05-12T04:59:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“짠…”\n\n그런 레마의 맥주 마시는 모습을 잠깐 바라본채 퀸시는 물을 마저 마셨다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100054","time":"2026-05-12T05:01:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“그러고보니… 이름도 아직 모르시겠네요.”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100055","time":"2026-05-12T05:01:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네. 저는 레마 캐롤라인이라고 해, 해요. 당신의 이름은요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100056","time":"2026-05-12T05:02:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“저는… 퀸시에요. 본명은 제르지 이스켄데르 퀸시인데요, 그냥 퀸시라고 불러주세요.”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100057","time":"2026-05-12T05:02:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"본명 이야기는 괜히 했나 싶어서 후회가 밀려왔다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100058","time":"2026-05-12T05:02:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 퀸시... 머, 멋진 이름이에요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100059","time":"2026-05-12T05:03:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"”레마씨도 멋진 이름이네요..”\n\n멋있다는 이야기는 처음 들어봐서 괜히 어설픈 웃음을 지었다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100060","time":"2026-05-12T05:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"쓰다듬고 싶다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100061","time":"2026-05-12T05:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"참아 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100062","time":"2026-05-12T05:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 식당에서 밤을 새, 새워도 괜찮겠어요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100063","time":"2026-05-12T05:04:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“… 괜찮아요. 어차피 잠은 다 깼으니깐요.“\n\n방금 전투하다가 온 듯한 몰골이다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100064","time":"2026-05-12T05:05:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“레마씨는… 졸리지 않으세요?“","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100065","time":"2026-05-12T05:05:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그러면 상처에 으, 응급처치라도 해 드릴게요. \"\n\n퀸시의 상처를 살피며.\n\n\" 졸리긴 하, 하지만... 퀸시 씨를 여기 호, 혼자 두고 싶진 않은걸요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100066","time":"2026-05-12T05:05:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100067","time":"2026-05-12T05:05:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[10] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0100068","time":"2026-05-12T05:06:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 퀸시의 상처를 능숙하게 응급처치 해 준다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100069","time":"2026-05-12T05:06:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“…?”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100070","time":"2026-05-12T05:07:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아직 길드원 드, 등록도 안 되셨는데 오해를 사면 고, 곤란하잖아요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100071","time":"2026-05-12T05:08:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"꽤나 작은 상처였지만, 레마의 치료 덕분에  내일이면 전부 멀쩡하게 돌아갈 것이다.\n\n“아… 그래서 그런거군요…”\n\n사실 아까 레마가 했던 말에 대한 이유가 궁금했는데, 실례가 될까봐 말하지 못했다! 퀸시는 이런 성격이니깐.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100072","time":"2026-05-12T05:09:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“그건..! 괜찮아요.. 제가 잘 말하면 될거에요.. 레마씨 늦은 시간에 감사해요.. 피곤하시면 어서 침대로…”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100073","time":"2026-05-12T05:10:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아, 아니에요. 지금 당장 졸리진 아, 않아요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100074","time":"2026-05-12T05:12:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“그… 그렇군요..”\n\n더 하면 가라는 강요가 되겠지. 그건 아니다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100075","time":"2026-05-12T05:12:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“저… 레마씨 혹시…..”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100076","time":"2026-05-12T05:12:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"질문해볼까 매우 고민하는 듯한 퀸시","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100077","time":"2026-05-12T05:13:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네, 어떤거 구, 궁금하신거 있으세요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100078","time":"2026-05-12T05:14:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“… 어설픈 용맹은 뭘 하는 곳인가요?”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100079","time":"2026-05-12T05:14:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"사실 오긴 했지만 정보는 거의 없었다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100080","time":"2026-05-12T05:14:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"뻘쭘.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100081","time":"2026-05-12T05:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 일단 기, 기본적으로는 의뢰를 바, 받아 해결하는 길드긴 한데요... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100082","time":"2026-05-12T05:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그런 시, 시시한 대답을 원하시는건 아, 아닌 것 같고... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100083","time":"2026-05-12T05:15:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어떤 사람들이 모, 모여서 어떤 가치를 마, 만들어 나가는지에 대한 지, 질문이죠? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100084","time":"2026-05-12T05:15:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그에 대한 다, 답은... 저도 잘 모, 모르겠어요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100085","time":"2026-05-12T05:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 저, 여기 처, 처음 왔을 때 민폐를 좀 많이 끼, 끼쳤었는데. 그런 저를 포, 포기하지 않고 나아가게 해 주, 주신 분들이거든요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100086","time":"2026-05-12T05:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 뭔가 많이 배, 배우고 싶지만... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100087","time":"2026-05-12T05:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아직 모, 모두 이해하진 못한 건 가, 같아요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100088","time":"2026-05-12T05:17:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"전자를 말한거긴 한데… 그러나 그보다 더 좋은 답변을 들은 것만 같다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100089","time":"2026-05-12T05:18:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“…. 좋네요..“","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100090","time":"2026-05-12T05:18:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"저도 그렇게 될 수 있을까요라는 질문을 하고 싶었지만 퀸시는 아직 마음속으로 삼켜버린다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100091","time":"2026-05-12T05:19:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“레마씨는 분명 잘 하실 수 있으실거에요..!”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100092","time":"2026-05-12T05:19:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 고, 고마워요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100093","time":"2026-05-12T05:21:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“….음.. 레마씨는 친절하시니까요..“","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100094","time":"2026-05-12T05:22:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"”자… 잘 배우실 수 있을거에요…! 게다가 알려주시는 분들이.. 착하신 분들이라면요!“","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100095","time":"2026-05-12T05:22:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 친절... \"\n\n드디어 받게 된... 칭찬! 자신이 많이 바뀌었다는 사실이 체감 되기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0100096","time":"2026-05-12T05:23:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"무슨 말을 해야할지 몰라 막 내뱉었지만, 아무튼 해야 할 말이라고 생각한 퀸시였다.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100097","time":"2026-05-12T05:24:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“포기하지 않고 이끌어주시는 분들도 중요하지만…. 포기하지 않는 자신도 중요하다고 생각해요..”","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100098","time":"2026-05-12T05:25:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"아직 그런 말을 하기에는 아무런 경험도, 자격도 없는 퀸시였지만.","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100099","time":"2026-05-12T05:34:00+09:00","room":"RP II","name":"제르지 이스켄데르 퀸시","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-8e942e4a6ada"]},{"id":"RP-II-0100100","time":"2026-05-12T05:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
